       });
     }
 
     if (titulo !== undefined) {
       atividade.titulo = titulo;
       banco.atualizarTitulo(atividade.id, titulo);
     }
     if (vagas !== undefined) {
       if (vagas < 1) {
         return res.status(422).json({
